from app.models import Customer


class CustomerAnonymizer:
    def __init__(self, session: Session, customer_id: int):
        self.session = session
        self.customer = session.get(Customer, customer_id)
        self._fields = {}

    def scrub_identity(self):
        self._fields = {'rut': None, 'email': None, 'phone': None, 'address': None}
        return self

    def keep_accounting_refs(self):
        self._fields['anonymized'] = True
        return self

    def apply(self) -> bool:
        for name, value in self._fields.items():
            setattr(self.customer, name, value)
        self.session.commit()
        return True


def anonymize_customer(session: Session, customer_id: int) -> bool:
    return (
        CustomerAnonymizer(session, customer_id)
        .scrub_identity()
        .keep_accounting_refs()
        .apply()
    )

