from app.models import Invoice


class InvoiceArchiver:
    def __init__(self, session: Session):
        self.session = session
        self._cutoff_days = 2190
        self._batch = 200

    def older_than(self, days: int):
        if days < 2190:
            raise ValueError('cannot archive inside the tax retention window')
        self._cutoff_days = days
        return self

    def batch_size(self, size: int):
        self._batch = size
        return self

    def mark_archived(self) -> int:
        cutoff = datetime.now(timezone.utc) - timedelta(days=self._cutoff_days)
        rows = (
            self.session.query(Invoice)
            .filter(Invoice.issued_at < cutoff, Invoice.archived.is_(False))
            .limit(self._batch)
            .all()
        )
        for row in rows:
            row.archived = True
        self.session.commit()
        return len(rows)


def archive_invoices(session: Session) -> int:
    return InvoiceArchiver(session).older_than(2190).batch_size(200).mark_archived()

