class ResetRequestHandler:
    def __init__(self, user):
        self.user = user
        self._channel = 'email'

    def via(self, channel: str):
        self._channel = channel
        return self

    def deliver(self) -> None:
        token = issue_reset_token(user_id=self.user.id)
        if self._channel == 'email':
            send_password_reset_email(to=self.user.email, token=token)

    def ack(self) -> JSONResponse:
        return JSONResponse({'detail': 'if the account exists, an email was sent'})


@router.post('/auth/forgot')
def forgot_password(email: str):
    user = User.objects.filter(email=email).first()
    if user is None:
        return ResetRequestHandler(None).ack()
    handler = ResetRequestHandler(user).via('email')
    handler.deliver()
    return handler.ack()

