from fastapi import APIRouter
from fastapi.responses import JSONResponse

from app.models import ApiKey

router = APIRouter()


class ApiKeyView:
    def __init__(self, key):
        self.key = key
        self._payload = {'id': key.id, 'label': key.label}

    def with_suffix(self):
        self._payload['suffix'] = self.key.value[-4:]
        return self

    def with_rotation(self):
        self._payload['rotated_at'] = self.key.rotated_at.isoformat()
        return self

    def render(self) -> JSONResponse:
        return JSONResponse(self._payload)


@router.get('/admin/api-keys/{key_id}')
def api_key_detail(key_id: int):
    key = ApiKey.objects.get(pk=key_id)
    return ApiKeyView(key).with_suffix().with_rotation().render()
